PlayPcSpeakerBeep proc far
push    ax              ; Classic PC speaker beep: programs PIT channel 2 (0x34DE/0x708 divisor) via ports 0x43/0x42, gates it to the speaker via port 0x61 bits 0-1, waits 4 ticks, then disables it. Called from TriggerSoundEvent's driver-inactive fallback path (ax==3).
push    bx
push    cx
push    dx
mov     cx, 708h
mov     dx, 12h
mov     ax, 34DEh
div     cx
out     42h, al         ; Timer 8253-5 (AT: 8254.2).
mov     al, ah
out     42h, al         ; Timer 8253-5 (AT: 8254.2).
in      al, 61h         ; PC/XT PPI port B bits:
                        ; 0: Tmr 2 gate ââ¦ââº OR 03H=spkr ON
                        ; 1: Tmr 2 data ââ  AND 0fcH=spkr OFF
                        ; 3: 1=read high switches
                        ; 4: 0=enable RAM parity checking
                        ; 5: 0=enable I/O channel check
                        ; 6: 0=hold keyboard clock low
                        ; 7: 0=enable kbrd
or      al, 3
out     61h, al         ; PC/XT PPI port B bits:
                        ; 0: Tmr 2 gate ââ¦ââº OR 03H=spkr ON
                        ; 1: Tmr 2 data ââ  AND 0fcH=spkr OFF
                        ; 3: 1=read high switches
                        ; 4: 0=enable RAM parity checking
                        ; 5: 0=enable I/O channel check
                        ; 6: 0=hold keyboard clock low
                        ; 7: 0=enable kbrd
mov     ax, 4           ; ticks
call    wait
in      al, 61h         ; PC/XT PPI port B bits:
                        ; 0: Tmr 2 gate ââ¦ââº OR 03H=spkr ON
                        ; 1: Tmr 2 data ââ  AND 0fcH=spkr OFF
                        ; 3: 1=read high switches
                        ; 4: 0=enable RAM parity checking
                        ; 5: 0=enable I/O channel check
                        ; 6: 0=hold keyboard clock low
                        ; 7: 0=enable kbrd
and     al, 0FCh
out     61h, al         ; PC/XT PPI port B bits:
                        ; 0: Tmr 2 gate ââ¦ââº OR 03H=spkr ON
                        ; 1: Tmr 2 data ââ  AND 0fcH=spkr OFF
                        ; 3: 1=read high switches
                        ; 4: 0=enable RAM parity checking
                        ; 5: 0=enable I/O channel check
                        ; 6: 0=hold keyboard clock low
                        ; 7: 0=enable kbrd
pop     dx
pop     cx
pop     bx
pop     ax
retf
PlayPcSpeakerBeep endp

