mov     [si+3], al
mov     al, [si+2]
adc     al, [di+2]
daa
mov     [si+2], al
mov     al, [si+1]
adc     al, [di+1]
daa
mov     [si+1], al
mov     al, [si]
adc     al, [di]
daa
mov     [si], al
retf
