loc_25842:              ; Video status bits:
in      al, dx          ; 0: retrace.  1=display is in vert or horiz retrace.
                        ; 1: 1=light pen is triggered; 0=armed
                        ; 2: 1=light pen switch is open; 0=closed
                        ; 3: 1=vertical sync pulse is occurring.
test    al, 8
jz      short loc_25842

loc_25847:
mov     dx, 3C8h
mov     al, bl
out     dx, al
inc     dx

loc_2584E:
lodsb
out     dx, al
lodsb
out     dx, al
lodsb
out     dx, al
loop    loc_2584E
retf
SetPaletteRange endp




GetPalette proc near
xor     bx, bx          ; BIOS INT 10h/AX=1017h: reads all 256 DAC palette registers into es:dx (768-byte RGB-triple buffer).
